/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_POLICY_COVERAGE_PARAMETER
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_POLICY   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : (not declared in data_7.js)
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_POLICY_HK, PARAMETER_REFERENCE, PLAN_REFERENCE, SECTION_REFERENCE, COVERAGE_REFERENCE
   hashdiff    : SAT_POLICY_COVERAGE_PARAMETER_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , coalesce(nullif(trim(PARAM_REF), ''), '') as PARAMETER_REFERENCE
        , coalesce(nullif(trim(PLAN_ID), ''), '') as PLAN_REFERENCE
        , coalesce(nullif(trim(SECTION_ID), ''), '') as SECTION_REFERENCE
        , coalesce(nullif(trim(CVR_CODE), ''), '') as COVERAGE_REFERENCE
        , PARAM_ID as PARAMETER_DEFINITION_REFERENCE
        , PARAM_VAL as PARAMETER_VALUE
        , 'BJAZ_CTNGY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        PARAMETER_REFERENCE,
        PLAN_REFERENCE,
        SECTION_REFERENCE,
        COVERAGE_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then PARAMETER_DEFINITION_REFERENCE end) as PARAMETER_DEFINITION_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then PARAMETER_VALUE end) as PARAMETER_VALUE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK, PARAMETER_REFERENCE, PLAN_REFERENCE, SECTION_REFERENCE, COVERAGE_REFERENCE
),

hashed as (
    select
        *,
        case when PARAMETER_REFERENCE is not null or PLAN_REFERENCE is not null or SECTION_REFERENCE is not null or COVERAGE_REFERENCE is not null or PARAMETER_DEFINITION_REFERENCE is not null or PARAMETER_VALUE is not null
                     then md5(upper(coalesce(cast(PARAMETER_REFERENCE as varchar), '') || '|' || coalesce(cast(PLAN_REFERENCE as varchar), '') || '|' || coalesce(cast(SECTION_REFERENCE as varchar), '') || '|' || coalesce(cast(COVERAGE_REFERENCE as varchar), '') || '|' || coalesce(cast(PARAMETER_DEFINITION_REFERENCE as varchar), '') || '|' || coalesce(cast(PARAMETER_VALUE as varchar), '')))
                end as SAT_POLICY_COVERAGE_PARAMETER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_COVERAGE_PARAMETER_HASHDIFF is not null
